package ch.jalu.configme.configurationdata;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class PropertyListBuilderTest {

    @Test
    public void addProperty_NullProperty_ThrowsConfigMeException() {
        Property<?> property = null;
        assertThrows(ConfigMeException.class, () -> new PropertyListBuilder().add(property));
    }

    @Test
    public void create_EmptyList_ReturnsEmptyList() {
        List<Property<?>> properties = new ArrayList<>();
        List<Property<?>> result = new PropertyListBuilder().create(properties);
        assertNull(result);
    }

    @Test
    public void addProperty_PropertysIsAddedToTheList() {
        Property<String> property1 = new Property<>("prop1", "value1");
        Property<String> property2 = new Property<>("prop2", "value2");

        List<Property<?>> properties = new ArrayList<>();
        new PropertyListBuilder().add(property1);
        new PropertyListBuilder().add(property2);

        List<Property<?>> result = new PropertyListBuilder().create(properties);
        assertEquals(2, result.size());
    }

    @Test
    public void getRootEntries_ReturnsEmptyMap() {
        Map<String, Object> entries = new PropertyListBuilder().getRootEntries();
        assertTrue(entries.isEmpty());
    }

}

